/* Tooltip — rendered as <button> so :focus-visible reveals popover for keyboard users */
.tooltip {
  display: inline-block;
  position: relative;
  cursor: help;
  background: transparent;
  border: none;
  padding: 0;
  margin: 0;
  line-height: 0;
}

.tooltip::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 80%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--color-text-primary);
  color: #fff;
  padding: 8px 12px;
  border-radius: 6px;
  font-size: 12px;
  white-space: normal;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease, bottom 0.25s ease;
  z-index: 9999;
  width: 200px;
  text-align: center;
}

.tooltip:hover::after,
.tooltip:focus-visible::after {
  opacity: 1;
  bottom: 90%;
}

.tooltip::before {
  content: '';
  position: absolute;
  bottom: 71%;
  left: 50%;
  transform: translateX(-50%);
  border: 6px solid transparent;
  border-top-color: var(--color-text-primary);
  opacity: 0;
  transition: opacity 0.25s ease;
}

.tooltip:hover::before,
.tooltip:focus-visible::before {
  opacity: 1;
}

.tooltipIco {
  width: 16px;
  height: 16px;
  opacity: 0.5;
}

