/* ============================================================
   CustomPlanCta — custom-plan-cta.module.css
   Matches Webflow .blue-sec.pricing-blue-sec.margin-btm-0
   + .book-section.remove-pattern + .heading-grid-small.margin-bottom-0
   ============================================================ */

/* blue-sec pricing-blue-sec margin-btm-0 */
.section {
  background-color: transparent;
  margin-bottom: 0;
  padding: 0 5%;
  position: relative;
}

/* container-large-3 */
.container {
  width: 100%;
  max-width: 1280px;
  margin-left: auto;
  margin-right: auto;
}

/* book-section remove-pattern */
.card {
  background-color: var(--color-text-primary);
  background-image: url('/images/webflow/Mask-group-1.png');
  background-position: 100% 100%;
  background-repeat: no-repeat;
  background-size: auto;
  -webkit-text-fill-color: inherit;
  background-clip: border-box;
  border-radius: 20px;
  padding: 40px 20px 50px;
}

/* heading-grid-small margin-bottom-0 */
.inner {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  grid-template-rows: auto;
  grid-template-columns: 1.25fr 0.25fr;
  place-items: center stretch;
  margin-bottom: 0;
  padding-left: 30px;
  padding-right: 30px;
  display: grid;
}

/* column-regular column-left */
.content {
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  flex-flow: column;
  justify-content: flex-start;
  align-items: flex-start;
  display: flex;
}

/* heading-2 white margin-top-0 hd-s left-mob */
.heading {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 36px;
  font-weight: 700;
  line-height: 52px;
  margin-top: 0;
  margin-bottom: 20px;
  text-align: left;
}

/* paragraph white text-left */
.subtitle {
  color: #fff;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1.125rem;
  line-height: 28px;
  text-align: left;
  margin-bottom: 20px;
}

/* custom-plan-dlexdiv */
.benefitsRow {
  grid-column-gap: 15px;
  grid-row-gap: 15px;
  flex-flow: wrap;
  display: flex;
  margin-bottom: 20px;
}

/* white-li-icon */
.benefitItem {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  color: #fff;
  align-items: center;
  margin-bottom: 2px;
  display: flex;
}

/* li-check-sky */

/* ─── Section wrapper ─────────────────────────────────────────────────────── */

.section {
  background-color: var(--color-brand-light-bg);
  padding: 80px 5%;
}

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* ─── Header ─────────────────────────────────────────────────────────────── */

.header {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  margin-bottom: 32px;
}

.eyebrowBadge {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 14px;
  background-color: rgba(33, 207, 255, 0.08);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 12px;
  font-weight: 700;
  color: var(--color-brand-card-border);
  letter-spacing: 0.04em;
  text-transform: capitalize;
}

.title {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 36px;
  font-weight: 700;
  line-height: 1.2;
  margin: 0;
  max-width: 580px;
}

.subtitle {
  color: rgba(8, 39, 83, 0.55);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  line-height: 26px;
  max-width: 520px;
  margin: 0;
}

/* ─── Preset buttons ─────────────────────────────────────────────────────── */

.presets {
  display: flex;
  justify-content: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 32px;
}

.presetBtn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background-color: #fff;
  border: 1px solid #e2e8f0;
  border-radius: var(--radius-pill);
  padding: 8px 18px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-primary);
  cursor: pointer;
  transition: border-color 0.15s ease, background-color 0.15s ease, color 0.15s ease;
}

.presetBtn:hover {
  border-color: var(--color-brand-card-border);
  color: var(--color-brand-card-border);
}

.presetBtnActive {
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  border-color: transparent;
  color: #fff;
}

.presetBtnActive:hover {
  color: #fff;
  filter: brightness(1.06);
}

/* ─── Two-column layout ──────────────────────────────────────────────────── */

.layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  align-items: start;
}

/* ─── Left panel ─────────────────────────────────────────────────────────── */

.leftPanel {
  background-color: #fff;
  border: 1px solid #e8eaed;
  border-radius: 20px;
  padding: 32px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  box-shadow: 0 4px 24px rgba(8, 39, 83, 0.06);
}

.panelTitle {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
}

/* ─── Plan selection block ───────────────────────────────────────────────── */

.planBlock {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Billing toggle */
.billingToggle {
  display: flex;
  background-color: var(--color-brand-light-bg);
  border-radius: 10px;
  padding: 5px 6px;
  gap: 4px;
}

